223:
SELECT c."atom_id", c."atom_id2"
FROM "connected" c
WHERE c."bond_id" = 'TR000_2_5';

319:
SELECT COUNT(DISTINCT c."atom_id") AS element_count
FROM "connected" c
WHERE c."bond_id" = 'TR001_3_4';

714:
SELECT c.*
FROM "comments" c
WHERE c."userdisplayname" = 'Harvey Motulsky';

661:
SELECT "u"."age"
FROM "users" "u"
WHERE "u"."reputation" = (
    SELECT MAX("reputation") FROM "users"
)
LIMIT 1;

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

572:
SELECT "p"."viewcount"
FROM "posts" AS "p"
WHERE "p"."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

745:
SELECT p."id"
FROM "publisher" AS p
WHERE p."publisher_name" = 'Star Trek';

803:
SELECT sp."id"
FROM "superpower" AS sp
WHERE LOWER(sp."power_name") = LOWER('cryokinesis');

747:
SELECT COUNT(*) AS superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(DISTINCT m."member_id") AS president_count
FROM "member" m
WHERE LOWER(TRIM(m."position")) = LOWER('President');
